t.script:
let opmsDeleteConfirmArmed = false;

function opmsShowBulkFeedback(message, level) {
    const box = document.getElementById("opms-bulk-feedback");
    if (!box) {
        return;
    }
    box.className = "alert opms-inline-feedback mb-3 alert-" + (level || "warning");
    box.textContent = message;
}

function submitBulkAction(action) {
    const selectedIds = Array.from(document.querySelectorAll(".opms-profile-checkbox:checked")).map(cb => cb.value);
    if (selectedIds.length === 0) {
        opmsShowBulkFeedback("Please select at least one profile.", "warning");
        opmsDeleteConfirmArmed = false;
        const deleteBtn = document.getElementById("opms-delete-selected-btn");
        if (deleteBtn) {
            deleteBtn.textContent = "Delete Selected";
        }
        return;
    }

    if (action === "delete" && !opmsDeleteConfirmArmed) {
        opmsDeleteConfirmArmed = true;
        opmsShowBulkFeedback("Click 'Delete Selected' again to confirm permanent deletion.", "danger");
        const deleteBtn = document.getElementById("opms-delete-selected-btn");
        if (deleteBtn) {
            deleteBtn.textContent = "Confirm Delete Selected";
        }
        return;
    }

    if (action !== "delete") {
        opmsDeleteConfirmArmed = false;
        const deleteBtn = document.getElementById("opms-delete-selected-btn");
        if (deleteBtn) {
            deleteBtn.textContent = "Delete Selected";
        }
    }

    document.getElementById("bulk_action_input").value = action;
    document.getElementById("opms-profiles-form").submit();
}

(function () {
    const master = document.getElementById("opms-select-all-profiles");
    if (!master) {
        return;
    }
    master.addEventListener("change", function () {
        document.querySelectorAll(".opms-profile-checkbox").forEach(function (cb) {
            cb.checked = master.checked;
        });
    });

    // Uncheck master when individual checkbox is unchecked
    document.querySelectorAll(".opms-profile-checkbox").forEach(function (cb) {
        cb.addEventListener("change", function () {
            const allChecked = Array.from(document.querySelectorAll(".opms-profile-checkbox"))
                .every(c => c.checked);
            master.checked = allChecked;
            if (opmsDeleteConfirmArmed) {
                opmsDeleteConfirmArmed = false;
                const deleteBtn = document.getElementById("opms-delete-selected-btn");
                if (deleteBtn) {
                    deleteBtn.textContent = "Delete Selected";
                }
            }
        });
    });
})();

(function () {
    const userSelect = document.querySelector('select[name="user_id"]');
    const companySelect = document.getElementById("opms-um-company-select");
    const companyHiddenInput = document.getElementById("opms-um-company-id");
    const companyLockNote = document.getElementById("opms-um-company-lock-note");
    const programmeSelect = document.getElementById("opms-um-programmes");
    const subProgrammeSelect = document.getElementById("opms-um-sub-programmes");
    const directorateSelect = document.getElementById("opms-um-directorates");
    if (!userSelect || !companySelect || !companyHiddenInput || !programmeSelect || !subProgrammeSelect || !directorateSelect) {
        return;
    }

    function syncCompanyHidden() {
        companyHiddenInput.value = companySelect.value || "";
    }

    function applyUserCompanyLock() {
        const selected = userSelect.options[userSelect.selectedIndex];
        const linkedCompanyId = String((selected && selected.getAttribute("data-company-id")) || "");

        if (linkedCompanyId) {
            companySelect.value = linkedCompanyId;
            companySelect.disabled = true;
            if (companyLockNote) {
                companyLockNote.style.display = "block";
            }
        } else {
            companySelect.disabled = false;
            if (companyLockNote) {
                companyLockNote.style.display = "none";
            }
        }
        syncCompanyHidden();
    }

    function selectedValues(selectEl) {
        return new Set(Array.from(selectEl.selectedOptions).map(function (opt) {
            return String(opt.value);
        }));
    }

    function filterSubProgrammes() {
        const programmes = selectedValues(programmeSelect);
        Array.from(subProgrammeSelect.options).forEach(function (opt) {
            const programmeId = String(opt.getAttribute("data-programme-id") || "");
            const visible = !programmes.size || programmes.has(programmeId);
            opt.hidden = !visible;
            if (!visible) {
                opt.selected = false;
            }
        });
    }

    function filterDirectorates() {
        const subProgrammes = selectedValues(subProgrammeSelect);
        Array.from(directorateSelect.options).forEach(function (opt) {
            const subProgrammeId = String(opt.getAttribute("data-sub-programme-id") || "");
            const visible = !subProgrammes.size || subProgrammes.has(subProgrammeId);
            opt.hidden = !visible;
            if (!visible) {
                opt.selected = false;
            }
        });
    }

    programmeSelect.addEventListener("change", function () {
        filterSubProgrammes();
        filterDirectorates();
    });
    subProgrammeSelect.addEventListener("change", filterDirectorates);
    companySelect.addEventListener("change", syncCompanyHidden);
    userSelect.addEventListener("change", applyUserCompanyLock);

    applyUserCompanyLock();
    syncCompanyHidden();
    filterSubProgrammes();
    filterDirectorates();
})();

                document.addEventListener('DOMContentLoaded', function () {
                    const summarySeed = document.getElementById('opms-target-summary-seed');
                    const inputSeed = document.getElementById('opms-target-input-seed');

                    function safeJsonParse(rawValue, fallback) {
                        try {
                            return JSON.parse(rawValue);
                        } catch (error) {
                            return fallback;
                        }
                    }

                    const initialTargetSummary = safeJsonParse((summarySeed && summarySeed.dataset.summary) || '{"visible": false}', { visible: false });
                    const initialTargetInput = safeJsonParse((inputSeed && inputSeed.dataset.input) || '{"visible": false}', { visible: false });
                    const steps = [
                        { id: 'financial_year_id', key: 'financial_years', placeholder: 'Select Financial Year' },
                        { id: 'programme_id', key: 'programmes', placeholder: 'Select Programme' },
                        { id: 'sub_programme_id', key: 'sub_programmes', placeholder: 'Select Sub-Programme' },
                        { id: 'directorate_id', key: 'directorates', placeholder: 'Select Directorate' },
                        { id: 'output_id', key: 'outputs', placeholder: 'Select Output' },
                        { id: 'output_indicator_id', key: 'output_indicators', placeholder: 'Select Output Indicator' },
                        { id: 'annual_target_id', key: 'annual_targets', placeholder: 'Select Annual Target' },
                        { id: 'quarter_id', key: 'quarters', placeholder: 'Select Quarter' },
                        { id: 'quarterly_target_id', key: 'quarterly_targets', placeholder: 'Select a Quarterly Target' }
                    ];

                    const existingSubmissionsCard = document.getElementById('opms-existing-submissions-card');
                    const targetSummaryCard = document.getElementById('opms-target-summary-card');
                    if (existingSubmissionsCard && targetSummaryCard && existingSubmissionsCard.parentNode === targetSummaryCard.parentNode) {
                        targetSummaryCard.insertAdjacentElement('afterend', existingSubmissionsCard);
                    }

                    const actualInputConfig = {
                        number: document.getElementById('opms-actual-number-input'),
                        date: document.getElementById('opms-actual-date-input'),
                        boolean: document.getElementById('opms-actual-boolean-input'),
                        text: document.getElementById('opms-actual-text-input'),
                        textarea: document.getElementById('opms-actual-textarea-input')
                    };

                    function formatDisplayToIsoDate(displayValue) {
                        const text = String(displayValue || '').trim();
                        const parts = text.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
                        if (!parts) {
                            return '';
                        }
                        const day = parseInt(parts[1], 10);
                        const month = parseInt(parts[2], 10);
                        const year = parseInt(parts[3], 10);
                        const candidate = new Date(year, month - 1, day);
                        if (candidate.getFullYear() !== year || candidate.getMonth() !== month - 1 || candidate.getDate() !== day) {
                            return '';
                        }
                        const mm = String(month).padStart(2, '0');
                        const dd = String(day).padStart(2, '0');
                        return year + '-' + mm + '-' + dd;
                    }

                    const submitDateInput = document.getElementById('opms-actual-date-input');
                    let fpSubmitDate = submitDateInput ? flatpickr(submitDateInput, { dateFormat: 'd/m/Y', disableMobile: true, onChange: function() { syncActualValue(); } }) : null;

                    function getVisibleActualInput(mode) {
                        return actualInputConfig[mode] || actualInputConfig.text;
                    }

                    function getCurrentInputMode() {
                        const activeEntry = Object.entries(actualInputConfig).find((entry) => entry[1] && !entry[1].classList.contains('d-none'));
                        return activeEntry ? activeEntry[0] : null;
                    }

                    function syncActualValue() {
                        const hidden = document.getElementById('actual_value');
                        if (!hidden) {
                            return;
                        }
                        const activeInput = Object.values(actualInputConfig).find((element) => element && !element.classList.contains('d-none'));
                        hidden.value = activeInput ? activeInput.value : '';
                    }

                    function renderTargetInput(config) {
                        const card = document.getElementById('opms-actual-input-card');
                        const label = document.getElementById('opms-actual-input-label');
                        const help = document.getElementById('opms-actual-input-help');
                        const hidden = document.getElementById('actual_value');
                        const currentMode = getCurrentInputMode();
                        const currentValue = hidden ? hidden.value : '';
                        if (!card) {
                            return;
                        }

                        const preserveCurrentValue = config && config.visible && currentMode === config.input_mode;
                        Object.values(actualInputConfig).forEach((element) => {
                            if (element) {
                                element.classList.add('d-none');
                                if (!preserveCurrentValue) {
                                    element.value = '';
                                }
                            }
                        });
                        if (hidden && !preserveCurrentValue) {
                            hidden.value = '';
                        }
                        syncActualValue();

                        if (!config || !config.visible) {
                            card.classList.add('d-none');
                            return;
                        }

                        card.classList.remove('d-none');
                        if (label) {
                            label.innerHTML = (config.label || 'Actual Output value for this submission') + ' *';
                        }
                        if (help) {
                            help.textContent = config.help_text || '';
                        }

                        const activeInput = getVisibleActualInput(config.input_mode);
                        if (activeInput) {
                            activeInput.classList.remove('d-none');
                            if (preserveCurrentValue) {
                                activeInput.value = currentValue;
                            }
                            if (config.placeholder && activeInput.tagName !== 'SELECT') {
                                activeInput.setAttribute('placeholder', config.placeholder);
                            }
                            if (config.input_mode === 'date') {
                                if (fpSubmitDate && preserveCurrentValue && currentValue) {
                                    fpSubmitDate.setDate(currentValue, false, 'd/m/Y');
                                }
                            }
                        }

                        // Keep hidden submission value aligned after each dynamic re-render.
                        syncActualValue();

                        if (config.aggregation_rule === 'count') {
                            card.classList.add('d-none');
                            if (help) {
                                help.textContent = 'This indicator uses submission count, so each new submission increases the actual by 1.';
                            }
                        }
                    }

                    function setText(id, value) {
                        const element = document.getElementById(id);
                        if (element) {
                            element.textContent = value || '-';
                        }
                    }

                    function renderMetric(prefix, metric) {
                        setText(prefix + '-title', metric.title);
                        setText(prefix + '-planned', metric.planned_display);
                        setText(prefix + '-actual', metric.actual_display);
                        setText(prefix + '-gap', metric.variance_display);
                        setText(prefix + '-projected', metric.projected_actual_display + ' (' + metric.projected_variance_display + ')');
                        setText(prefix + '-note', metric.note || '');
                    }

                    const existingSubmissionsStateKey = 'opmsExistingSubmissionsStateV2';
                    const existingSubmissionsPageSize = 10;

                    function getExistingSubmissionsTableState() {
                        const fallback = { sort: { by: 'date', dir: 'desc' }, page: 1 };
                        try {
                            const raw = window.sessionStorage.getItem(existingSubmissionsStateKey);
                            if (!raw) { return fallback; }
                            const parsed = JSON.parse(raw);
                            const allowedSortKeys = ['id', 'name', 'quarter', 'status', 'progress', 'planned_value', 'actual_value', 'submitted_by', 'date'];
                            const sortBy = allowedSortKeys.includes((parsed.sort || {}).by) ? parsed.sort.by : fallback.sort.by;
                            const sortDir = ['asc', 'desc'].includes((parsed.sort || {}).dir) ? parsed.sort.dir : fallback.sort.dir;
                            const page = Number.isInteger(parsed.page) && parsed.page > 0 ? parsed.page : 1;
                            return { sort: { by: sortBy, dir: sortDir }, page: page };
                        } catch (error) {
                            return fallback;
                        }
                    }

                    function persistExistingSubmissionsTableState() {
                        try {
                            window.sessionStorage.setItem(existingSubmissionsStateKey, JSON.stringify({
                                sort: window.__opmsExistingSortState || { by: 'date', dir: 'desc' },
                                page: window.__opmsExistingPage || 1,
                            }));
                        } catch (error) {
                            // Ignore storage failures and keep in-memory sorting.
                        }
                    }

                    function renderExistingSubmissions(submissions) {
                        const card = document.getElementById('opms-existing-submissions-card');
                        const badge = document.getElementById('opms-existing-submissions-badge');
                        const tbody = document.getElementById('opms-existing-submissions-body');
                        if (!card || !tbody) { return; }
                        tbody.innerHTML = '';
                        const list = Array.isArray(submissions) ? submissions.slice() : [];
                        if (!list.length) {
                            card.classList.add('d-none');
                            return;
                        }

                        if (!window.__opmsExistingSortState || !window.__opmsExistingPage) {
                            const savedState = getExistingSubmissionsTableState();
                            window.__opmsExistingSortState = savedState.sort;
                            window.__opmsExistingPage = savedState.page;
                        }

                        function getDateValue(value) {
                            const text = String(value || '').trim();
                            if (!text) {
                                return 0;
                            }
                            const directMatch = text.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
                            if (directMatch) {
                                const day = parseInt(directMatch[1], 10);
                                const month = parseInt(directMatch[2], 10);
                                const year = parseInt(directMatch[3], 10);
                                const dateObj = new Date(year, month - 1, day);
                                if (dateObj.getFullYear() === year && dateObj.getMonth() === month - 1 && dateObj.getDate() === day) {
                                    return dateObj.getTime();
                                }
                            }
                            const parsed = Date.parse(text);
                            if (!Number.isNaN(parsed)) {
                                return parsed;
                            }
                            return 0;
                        }

                        function compareText(left, right) {
                            return String(left || '').localeCompare(String(right || ''), undefined, { sensitivity: 'base' });
                        }

                        function compareActual(left, right) {
                            const leftNum = parseFloat(String(left || '').replace(/[^0-9.+\-]/g, ''));
                            const rightNum = parseFloat(String(right || '').replace(/[^0-9.+\-]/g, ''));
                            if (!Number.isNaN(leftNum) && !Number.isNaN(rightNum)) {
                                return leftNum - rightNum;
                            }
                            return compareText(left, right);
                        }

                        function updateExistingSortHeader() {
                            const state = window.__opmsExistingSortState;
                            const idEl = document.getElementById('opms-existing-sort-id');
                            const nameEl = document.getElementById('opms-existing-sort-name');
                            const quarterEl = document.getElementById('opms-existing-sort-quarter');
                            const statusEl = document.getElementById('opms-existing-sort-status');
                            const progressEl = document.getElementById('opms-existing-sort-progress');
                            const plannedValueEl = document.getElementById('opms-existing-sort-planned-value');
                            const actualValueEl = document.getElementById('opms-existing-sort-actual-value');
                            const submittedByEl = document.getElementById('opms-existing-sort-submitted-by');
                            const dateEl = document.getElementById('opms-existing-sort-date');
                            if (idEl) {
                                idEl.innerHTML = '#' + (state.by === 'id' ? (state.dir === 'asc' ? ' ▲' : ' ▼') : '');
                            }
                            if (nameEl) {
                                nameEl.innerHTML = 'Name' + (state.by === 'name' ? (state.dir === 'asc' ? ' ▲' : ' ▼') : '');
                            }
                            if (quarterEl) {
                                quarterEl.innerHTML = 'Quarter' + (state.by === 'quarter' ? (state.dir === 'asc' ? ' ▲' : ' ▼') : '');
                            }
                            if (statusEl) {
                                statusEl.innerHTML = 'Status' + (state.by === 'status' ? (state.dir === 'asc' ? ' ▲' : ' ▼') : '');
                            }
                            if (progressEl) {
                                progressEl.innerHTML = 'Progress' + (state.by === 'progress' ? (state.dir === 'asc' ? ' ▲' : ' ▼') : '');
                            }
                            if (plannedValueEl) {
                                plannedValueEl.innerHTML = 'Planned Value' + (state.by === 'planned_value' ? (state.dir === 'asc' ? ' ▲' : ' ▼') : '');
                            }
                            if (actualValueEl) {
                                actualValueEl.innerHTML = 'Actual Value' + (state.by === 'actual_value' ? (state.dir === 'asc' ? ' ▲' : ' ▼') : '');
                            }
                            if (submittedByEl) {
                                submittedByEl.innerHTML = 'Submitted By' + (state.by === 'submitted_by' ? (state.dir === 'asc' ? ' ▲' : ' ▼') : '');
                            }
                            if (dateEl) {
                                dateEl.innerHTML = 'Date' + (state.by === 'date' ? (state.dir === 'asc' ? ' ▲' : ' ▼') : '');
                            }
                        }

                        function sortExistingRows(rows) {
                            const state = window.__opmsExistingSortState;
                            const sorted = rows.slice().sort(function (a, b) {
                                if (state.by === 'id') {
                                    return (a.id || 0) - (b.id || 0);
                                }
                                if (state.by === 'submitted_by') {
                                    return compareText(a.submitted_by, b.submitted_by);
                                }
                                if (state.by === 'quarter') {
                                    return compareText(a.quarter_code || a.quarter_label, b.quarter_code || b.quarter_label);
                                }
                                if (state.by === 'date') {
                                    return getDateValue(a.submission_date) - getDateValue(b.submission_date);
                                }
                                if (state.by === 'planned_value') {
                                    return compareActual(a.planned_value, b.planned_value);
                                }
                                if (state.by === 'actual_value') {
                                    return compareActual(a.actual_value, b.actual_value);
                                }
                                if (state.by === 'status') {
                                    return compareText(a.workflow_status, b.workflow_status);
                                }
                                if (state.by === 'progress') {
                                    return compareText(a.comments, b.comments);
                                }
                                return compareText(a.name, b.name);
                            });
                            if (state.dir === 'desc') {
                                sorted.reverse();
                            }
                            return sorted;
                        }

                        function bindExistingSortHeader(id, key) {
                            const el = document.getElementById(id);
                            if (!el || el.dataset.bound) { return; }
                            el.dataset.bound = '1';
                            el.addEventListener('click', function (ev) {
                                ev.preventDefault();
                                const state = window.__opmsExistingSortState;
                                if (state.by === key) {
                                    state.dir = state.dir === 'asc' ? 'desc' : 'asc';
                                } else {
                                    state.by = key;
                                    state.dir = key === 'date' ? 'desc' : 'asc';
                                }
                                window.__opmsExistingPage = 1;
                                persistExistingSubmissionsTableState();
                                renderExistingSubmissions(submissions);
                            });
                        }
                        bindExistingSortHeader('opms-existing-sort-id', 'id');
                        bindExistingSortHeader('opms-existing-sort-name', 'name');
                        bindExistingSortHeader('opms-existing-sort-quarter', 'quarter');
                        bindExistingSortHeader('opms-existing-sort-status', 'status');
                        bindExistingSortHeader('opms-existing-sort-progress', 'progress');
                        bindExistingSortHeader('opms-existing-sort-planned-value', 'planned_value');
                        bindExistingSortHeader('opms-existing-sort-actual-value', 'actual_value');
                        bindExistingSortHeader('opms-existing-sort-submitted-by', 'submitted_by');
                        bindExistingSortHeader('opms-existing-sort-date', 'date');

                        const prevBtn = document.getElementById('opms-existing-page-prev');
                        const nextBtn = document.getElementById('opms-existing-page-next');
                        if (prevBtn && !prevBtn.dataset.bound) {
                            prevBtn.dataset.bound = '1';
                            prevBtn.addEventListener('click', function () {
                                if ((window.__opmsExistingPage || 1) > 1) {
                                    window.__opmsExistingPage = (window.__opmsExistingPage || 1) - 1;
                                    persistExistingSubmissionsTableState();
                                    renderExistingSubmissions(submissions);
                                }
                            });
                        }
                        if (nextBtn && !nextBtn.dataset.bound) {
                            nextBtn.dataset.bound = '1';
                            nextBtn.addEventListener('click', function () {
                                window.__opmsExistingPage = (window.__opmsExistingPage || 1) + 1;
                                persistExistingSubmissionsTableState();
                                renderExistingSubmissions(submissions);
                            });
                        }

                        const sortedList = sortExistingRows(list);
                        const totalRows = sortedList.length;
                        const totalPages = Math.max(1, Math.ceil(totalRows / existingSubmissionsPageSize));
                        if ((window.__opmsExistingPage || 1) > totalPages) {
                            window.__opmsExistingPage = totalPages;
                        }
                        const page = window.__opmsExistingPage || 1;
                        const start = (page - 1) * existingSubmissionsPageSize;
                        const pageList = sortedList.slice(start, start + existingSubmissionsPageSize);
                        updateExistingSortHeader();

                        card.classList.remove('d-none');
                        if (badge) { badge.textContent = sortedList.length + ' submission' + (sortedList.length !== 1 ? 's' : ''); }
                        const pageInfo = document.getElementById('opms-existing-pagination-info');
                        if (pageInfo) {
                            const from = totalRows ? (start + 1) : 0;
                            const to = totalRows ? Math.min(start + existingSubmissionsPageSize, totalRows) : 0;
                            pageInfo.textContent = 'Showing ' + from + '-' + to + ' of ' + totalRows + ' (Page ' + page + ' of ' + totalPages + ')';
                        }
                        if (prevBtn) { prevBtn.disabled = page <= 1; }
                        if (nextBtn) { nextBtn.disabled = page >= totalPages; }

                        const statusColors = {
                            'Approved': 'success', 'Submitted': 'primary', 'Director Review': 'info',
                            'Draft': 'secondary', 'Rejected': 'danger'
                        };
                        pageList.forEach((sub, idx) => {
                            const tr = document.createElement('tr');
                            tr.setAttribute('data-sub-id', String(sub.id || ''));
                            tr.style.cursor = 'pointer';
                            tr.title = 'Click to view in All Submissions';
                            const statusColor = statusColors[sub.workflow_status] || 'secondary';
                            const safeComment = (sub.comments || '-');
                            const shortComment = safeComment.length > 80 ? safeComment.substring(0, 80) + '\u2026' : safeComment;
                            const numCell = document.createElement('td');
                            numCell.className = 'text-muted';
                            numCell.textContent = String(start + idx + 1);
                            const nameCell = document.createElement('td');
                            const strong = document.createElement('strong');
                            strong.textContent = sub.name || '-';
                            nameCell.appendChild(strong);
                            const quarterCell = document.createElement('td');
                            const quarterBadge = document.createElement('span');
                            quarterBadge.className = 'badge bg-light text-dark border';
                            quarterBadge.textContent = sub.quarter_code || sub.quarter_label || '-';
                            quarterCell.appendChild(quarterBadge);
                            const statusCell = document.createElement('td');
                            const span = document.createElement('span');
                            span.className = 'badge text-bg-' + statusColor;
                            span.textContent = sub.workflow_status || '-';
                            statusCell.appendChild(span);
                            const commentCell = document.createElement('td');
                            const smallComment = document.createElement('small');
                            smallComment.className = 'text-muted';
                            smallComment.textContent = shortComment;
                            commentCell.appendChild(smallComment);
                            const plannedCell = document.createElement('td');
                            plannedCell.textContent = sub.planned_value || '-';
                            const actualCell = document.createElement('td');
                            actualCell.textContent = sub.actual_value || '-';
                            const byCell = document.createElement('td');
                            byCell.textContent = sub.submitted_by || '-';
                            const dateCell = document.createElement('td');
                            const small = document.createElement('small');
                            small.textContent = sub.submission_date || '-';
                            dateCell.appendChild(small);
                            // Actions cell
                            const actionsCell = document.createElement('td');
                            actionsCell.className = 'text-nowrap';
                            const isOpen = sub.is_quarter_open === true;
                            const viewBtn = document.createElement('button');
                            viewBtn.type = 'button';
                            viewBtn.className = 'btn btn-sm btn-outline-secondary opms-sub-action-view me-1';
                            viewBtn.innerHTML = '<i class="fa fa-eye"/>';
                            viewBtn.title = 'View in All Submissions';
                            viewBtn.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); scrollToSubmission(sub.id); });
                            const editBtn = document.createElement('button');
                            editBtn.type = 'button';
                            editBtn.className = 'btn btn-sm me-1 ' + (isOpen ? 'btn-outline-primary opms-sub-action-edit' : 'btn-outline-secondary opms-sub-action-locked');
                            editBtn.innerHTML = isOpen ? '<i class="fa fa-pencil"/>' : '<i class="fa fa-lock"/>';
                            editBtn.title = isOpen ? 'Edit this submission' : 'Quarter is closed \u2014 editing is locked';
                            editBtn.disabled = !isOpen;
                            if (isOpen) { editBtn.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); openEditModal(sub.id); }); }
                            actionsCell.appendChild(viewBtn);
                            actionsCell.appendChild(editBtn);
                            tr.appendChild(numCell);
                            tr.appendChild(nameCell);
                            tr.appendChild(quarterCell);
                            tr.appendChild(statusCell);
                            tr.appendChild(plannedCell);
                            tr.appendChild(actualCell);
                            tr.appendChild(byCell);
                            tr.appendChild(commentCell);
                            tr.appendChild(dateCell);
                            tr.appendChild(actionsCell);
                            // Row click → navigate to All Submissions
                            tr.addEventListener('click', function () { scrollToSubmission(sub.id); });
                            tbody.appendChild(tr);
                        });

                        persistExistingSubmissionsTableState();
                    }

                    function renderTargetSummary(summary) {
                        const card = document.getElementById('opms-target-summary-card');
                        if (!card) {
                            return;
                        }
                        if (!summary || !summary.visible) {
                            card.classList.add('d-none');
                            renderTargetInput({ visible: false });
                            return;
                        }
                        card.classList.remove('d-none');
                        setText('opms-summary-heading', summary.heading);
                        const submissionNameEl = document.querySelector('[name="submission_name"]');
                        const narrativeNameEl = document.querySelector('[name="narrative_name"]');
                        if (submissionNameEl) { submissionNameEl.value = summary.heading || ''; }
                        if (narrativeNameEl) { narrativeNameEl.value = summary.heading ? 'Narrative Title - ' + summary.heading : ''; }
                        setText('opms-summary-subheading', summary.subheading);
                        renderMetric('opms-annual', summary.annual || {});
                        renderMetric('opms-quarterly', summary.quarterly || {});
                        renderTargetInput(summary.target_input || { visible: false });
                    }

function renderQuarterStatusBanner(quarterState) {
                        const outerBanner = document.getElementById('opms-quarter-status-banner');
                        const openAlert = document.getElementById('opms-quarter-open-alert');
                        const closedAlert = document.getElementById('opms-quarter-closed-alert');
                        const closedCard = document.getElementById('opms-selected-quarter-closed-card');
                        const selectedClosedBanner = document.querySelector('#opms-selected-quarter-closed-card .opms-selected-quarter-closed-banner');
                        const submitBtn = document.getElementById('opms-submit-btn');
                        const downstreamIds = [
                            'opms-existing-submissions-card',
                            'opms-target-values-card',
                            'opms-target-summary-card',
                            'opms-actual-input-card',
                            'opms-submission-details-card',
                            'opms-form-actions',
                        ];

                        if (!quarterState || !outerBanner) {
                            if (outerBanner) { outerBanner.classList.add('d-none'); }
                            if (openAlert) { openAlert.classList.add('d-none'); }
                            if (closedAlert) { closedAlert.classList.add('d-none'); }
                            if (closedCard) { closedCard.classList.add('d-none'); }
                            if (selectedClosedBanner) { selectedClosedBanner.classList.remove('opms-closed-banner-pulse'); }
                            // Default state: keep all downstream sections hidden until an open quarter is selected.
                            downstreamIds.forEach(function (id) {
                                const el = document.getElementById(id);
                                if (el) { el.classList.add('opms-period-locked', 'd-none'); }
                            });
                            if (submitBtn) { submitBtn.disabled = false; submitBtn.classList.remove('disabled'); }
                            return;
                        }

                        const isOpen = quarterState.state === 'open';
                        const quarterLabel = quarterState.label || '-';
                        const windowText = (quarterState.open_date || '-') + ' to ' + (quarterState.close_date || '-');

                        outerBanner.classList.remove('d-none');

                        if (isOpen) {
                            openAlert.classList.remove('d-none');
                            closedAlert.classList.add('d-none');
                            if (closedCard) { closedCard.classList.add('d-none'); }
                            if (selectedClosedBanner) { selectedClosedBanner.classList.remove('opms-closed-banner-pulse'); }
                            setText('opms-quarter-open-label', quarterLabel);
                            setText('opms-quarter-open-dates', windowText);
                            // Unlock all sections
                            downstreamIds.forEach(function (id) {
                                const el = document.getElementById(id);
                                if (el) { el.classList.remove('opms-period-locked', 'd-none'); }
                            });
                            if (submitBtn) { submitBtn.disabled = false; submitBtn.classList.remove('disabled'); }
                        } else {
                            openAlert.classList.add('d-none');
                            closedAlert.classList.remove('d-none');
                            if (closedCard) { closedCard.classList.remove('d-none'); }
                            setText('opms-quarter-closed-label', quarterLabel);
                            setText('opms-quarter-closed-dates', windowText);
                            setText('opms-selected-quarter-closed-label', quarterLabel);
                            setText('opms-selected-quarter-closed-status', 'Closed');
                            setText('opms-selected-quarter-closed-open-date', quarterState.open_date || '-');
                            setText('opms-selected-quarter-closed-close-date', quarterState.close_date || '-');
                            setText('opms-selected-quarter-closed-dates', windowText);
                            if (selectedClosedBanner) {
                                selectedClosedBanner.classList.remove('opms-closed-banner-pulse');
                                void selectedClosedBanner.offsetWidth;
                                selectedClosedBanner.classList.add('opms-closed-banner-pulse');
                            }
                            // Lock all downstream sections
                            downstreamIds.forEach(function (id) {
                                const el = document.getElementById(id);
                                if (el) { el.classList.add('opms-period-locked', 'd-none'); }
                            });
                            if (submitBtn) {
                                submitBtn.disabled = true;
                                submitBtn.title = 'Submissions are currently closed for this quarter';
                                submitBtn.classList.add('disabled');
                            }
                        }
                    }

                    function refillSelect(selectId, values, placeholder) {
                        const select = document.getElementById(selectId);
                        if (!select) {
                            return;
                        }
                        select.replaceChildren();
                        const defaultOption = document.createElement('option');
                        defaultOption.value = '';
                        defaultOption.textContent = placeholder;
                        select.appendChild(defaultOption);
                        (values || []).forEach((entry) => {
                            const option = document.createElement('option');
                            option.value = entry.id;
                            option.textContent = entry.name;
                            select.appendChild(option);
                        });
                    }

                    function syncTargetValuesSectionVisibility() {
                        const targetValuesCard = document.getElementById('opms-target-values-card');
                        if (!targetValuesCard) {
                            return;
                        }
                        const annualStep = document.getElementById('step-annual_target_id');
                        const quarterlyStep = document.getElementById('step-quarterly_target_id');
                        const quarterSelect = document.getElementById('quarter_id');
                        const quarterOpenAlert = document.getElementById('opms-quarter-open-alert');
                        const hasQuarterSelection = quarterSelect && !!quarterSelect.value;
                        const isQuarterOpen = quarterOpenAlert && !quarterOpenAlert.classList.contains('d-none');
                        const showCard =
                            hasQuarterSelection &&
                            isQuarterOpen &&
                            (
                                (annualStep && !annualStep.classList.contains('d-none')) ||
                                (quarterlyStep && !quarterlyStep.classList.contains('d-none'))
                            );
                        targetValuesCard.classList.toggle('d-none', !showCard);
                    }

                    function setStepVisible(stepId, visible) {
                        const container = document.getElementById('step-' + stepId);
                        if (!container) {
                            return;
                        }
                        container.classList.toggle('d-none', !visible);
                        syncTargetValuesSectionVisibility();
                    }

                    function updateProgress() {
                        const filledCount = steps.reduce((count, step) => {
                            const value = (document.getElementById(step.id) || {}).value;
                            return value ? count + 1 : count;
                        }, 0);
                        const currentStep = Math.min(filledCount + 1, steps.length);
                        const percent = Math.round((filledCount / steps.length) * 100);

                        const label = document.getElementById('opms-progress-label');
                        const percentLabel = document.getElementById('opms-progress-percent');
                        const bar = document.getElementById('opms-progress-bar');

                        if (label) {
                            label.textContent = 'Step ' + currentStep + ' of ' + steps.length;
                        }
                        if (percentLabel) {
                            percentLabel.textContent = percent + '%';
                        }
                        if (bar) {
                            bar.style.width = percent + '%';
                            bar.setAttribute('aria-valuenow', String(percent));
                        }
                    }

                    const autoResolveFields = {
                        annual_target_id: { displayId: 'annual-target-resolved', labelId: 'annual-target-resolved-label' },
                        quarterly_target_id: { displayId: 'quarterly-target-resolved', labelId: 'quarterly-target-resolved-label' },
                    };

                    function resetFromIndex(startIndex) {
                        for (let i = startIndex; i < steps.length; i += 1) {
                            const step = steps[i];
                            const select = document.getElementById(step.id);
                            const arCfg = autoResolveFields[step.id];
                            if (select) {
                                select.value = '';
                                if (arCfg) {
                                    select.classList.add('visually-hidden');
                                    if (step.id === 'quarterly_target_id') {
                                        select.required = false;
                                    }
                                    const opt = document.createElement('option');
                                    opt.value = '';
                                    opt.textContent = '-';
                                    select.replaceChildren(opt);
                                } else {
                                    refillSelect(step.id, [], step.placeholder);
                                }
                            }
                            if (arCfg) {
                                const displayEl = document.getElementById(arCfg.displayId);
                                if (displayEl) {
                                    displayEl.classList.add('d-none');
                                }
                            }
                            if (i > 0) {
                                setStepVisible(step.id, false);
                            }
                        }
                    }

                    function selectedParams(uptoIndex) {
                        const params = new URLSearchParams();

                        const normalizedId = (value) => {
                            const strValue = String(value || '').trim();
                            return /^\d+$/.test(strValue) ? strValue : '';
                        };

                        for (let i = 0; i <= uptoIndex; i += 1) {
                            const id = steps[i].id;
                            const value = normalizedId((document.getElementById(id) || {}).value);
                            if (value) {
                                params.set(id, value);
                            }
                        }
                        const hiddenActualValue = document.getElementById('actual_value');
                        if (hiddenActualValue && hiddenActualValue.value) {
                            params.set('preview_actual_value', hiddenActualValue.value);
                        }
                        return params;
                    }

                    async function fetchSelectionState(uptoIndex) {
                        const response = await fetch('/my/opms/hierarchy/options?' + selectedParams(uptoIndex).toString(), {
                            credentials: 'same-origin',
                        });
                        if (!response.ok) {
                            return null;
                        }
                        return response.json();
                    }

                    async function loadNextStep(currentIndex) {
                        const currentStep = steps[currentIndex];
                        const nextStep = steps[currentIndex + 1];
                        const currentValue = (document.getElementById(currentStep.id) || {}).value;

                        resetFromIndex(currentIndex + 1);
                        if (!nextStep || !currentValue) {
                            const summaryIndex = currentValue ? currentIndex : currentIndex - 1;
                            const payload = summaryIndex >= 0 ? await fetchSelectionState(summaryIndex) : null;
                            renderQuarterStatusBanner(payload ? payload.quarter_submission_state : null);
                            const qState = payload ? payload.quarter_submission_state : null;
                            if (!qState || qState.state === 'open') {
                                renderTargetSummary(payload ? payload.target_summary : initialTargetSummary);
                                renderExistingSubmissions(payload ? payload.existing_submissions : []);
                            } else {
                                renderTargetSummary({ visible: false });
                                renderExistingSubmissions([]);
                            }
                            updateProgress();
                            return;
                        }

                        const payload = await fetchSelectionState(currentIndex);
                        if (!payload) {
                            return;
                        }

                        // Gate on quarter submission period state
                        renderQuarterStatusBanner(payload.quarter_submission_state);
                        if (currentStep.id === 'quarter_id' && payload.quarter_submission_state && payload.quarter_submission_state.state !== 'open') {
                            renderTargetSummary({ visible: false });
                            renderExistingSubmissions([]);
                            updateProgress();
                            return;
                        }
                        const nextOptions = payload[nextStep.key] || [];
                        const nextStepIndex = currentIndex + 1;
                        const arCfg = autoResolveFields[nextStep.id];

                        if (arCfg) {
                            const selectEl = document.getElementById(nextStep.id);
                            const displayEl = document.getElementById(arCfg.displayId);
                            const labelEl = document.getElementById(arCfg.labelId);
                            if (nextOptions.length === 1) {
                                if (selectEl) {
                                    selectEl.classList.add('visually-hidden');
                                    if (nextStep.id === 'quarterly_target_id') {
                                        selectEl.required = false;
                                    }
                                    const opt = document.createElement('option');
                                    opt.value = String(nextOptions[0].id);
                                    opt.textContent = nextOptions[0].name;
                                    opt.selected = true;
                                    selectEl.replaceChildren(opt);
                                    selectEl.value = String(nextOptions[0].id);
                                }
                                if (displayEl) {
                                    displayEl.classList.remove('d-none');
                                }
                                if (labelEl) {
                                    labelEl.textContent = nextOptions[0].name;
                                }
                                setStepVisible(nextStep.id, true);
                                await loadNextStep(nextStepIndex);
                                return;
                            }
                            if (nextOptions.length > 1) {
                                if (selectEl) {
                                    selectEl.classList.remove('visually-hidden');
                                    if (nextStep.id === 'quarterly_target_id') {
                                        selectEl.required = true;
                                    }
                                }
                                if (displayEl) {
                                    displayEl.classList.add('d-none');
                                }
                                refillSelect(nextStep.id, nextOptions, nextStep.placeholder);
                                setStepVisible(nextStep.id, true);
                            } else {
                                if (selectEl && nextStep.id === 'quarterly_target_id') {
                                    selectEl.required = false;
                                }
                                setStepVisible(nextStep.id, false);
                            }
                        } else {
                            refillSelect(nextStep.id, nextOptions, nextStep.placeholder);
                            setStepVisible(nextStep.id, nextOptions.length > 0);
                        }
                        renderTargetSummary(payload.target_summary);
                        renderExistingSubmissions(payload.existing_submissions || []);
                        updateProgress();
                    }

                    // Keep first step visible and all others hidden until previous is selected.
                    setStepVisible('financial_year_id', true);
                    resetFromIndex(1);
                    renderTargetInput(initialTargetInput);
                    renderTargetSummary(initialTargetSummary);
                    renderQuarterStatusBanner(null);
                    renderExistingSubmissions([]);
                    updateProgress();

                    steps.forEach((step, index) => {
                        const select = document.getElementById(step.id);
                        if (select) {
                            select.addEventListener('change', () => {
                                loadNextStep(index);
                            });
                        }
                    });

                    const initialFinancialYearSelect = document.getElementById('financial_year_id');
                    if (initialFinancialYearSelect && initialFinancialYearSelect.value) {
                        loadNextStep(0);
                    }


                    const form = document.getElementById('opms-portal-submission-form');
                    const evidenceInput = form ? form.querySelector('input[name="evidence_files"]') : null;

                    function isPdfFile(file) {
                        const fileName = String((file && file.name) || '').toLowerCase();
                        const mimeType = String((file && file.type) || '').toLowerCase();
                        return fileName.endsWith('.pdf') && (mimeType === '' || mimeType === 'application/pdf');
                    }

                    function validateEvidenceSelection() {
                        if (!evidenceInput || !evidenceInput.files || !evidenceInput.files.length) {
                            return true;
                        }
                        const invalid = Array.from(evidenceInput.files).find(function (file) { return !isPdfFile(file); });
                        if (invalid) {
                            evidenceInput.value = '';
                            showSubmissionNotice('Only PDF files are allowed for Evidence uploads.', 'warning');
                            return false;
                        }
                        return true;
                    }

                    if (evidenceInput) {
                        evidenceInput.addEventListener('change', function () {
                            validateEvidenceSelection();
                        });
                    }

                    if (form) {
                        form.addEventListener('submit', (event) => {
                            if (!validateEvidenceSelection()) {
                                event.preventDefault();
                                return;
                            }
                            const quarterlyTarget = document.getElementById('quarterly_target_id');
                            if (!quarterlyTarget || !quarterlyTarget.value) {
                                event.preventDefault();
                                showSubmissionNotice('Please complete the target selection before submitting.', 'warning');
                                return;
                            }

                            // Check if submission period is closed
                            const submitBtn = document.getElementById('opms-submit-btn');
                            if (submitBtn && submitBtn.disabled) {
                                event.preventDefault();
                                showSubmissionNotice('Submissions are currently closed for this quarter. Please contact your administrator if you believe this is an error.', 'warning');
                                return;
                            }
                        });
                    }

                    Object.values(actualInputConfig).forEach((element) => {
                        if (element) {
                            element.addEventListener('input', async () => {
                                syncActualValue();
                                const quarterlyTarget = document.getElementById('quarterly_target_id');
                                if (!quarterlyTarget || !quarterlyTarget.value) {
                                    return;
                                }
                                const payload = await fetchSelectionState(steps.length - 1);
                                if (payload) {
                                    renderTargetSummary(payload.target_summary);
                                }
                            });
                            element.addEventListener('change', async () => {
                                syncActualValue();
                                const quarterlyTarget = document.getElementById('quarterly_target_id');
                                if (!quarterlyTarget || !quarterlyTarget.value) {
                                    return;
                                }
                                const payload = await fetchSelectionState(steps.length - 1);
                                if (payload) {
                                    renderTargetSummary(payload.target_summary);
                                }
                            });
                        }
                    });

                    function scrollToSubmission(subId) {
                        const targetId = encodeURIComponent(String(subId || ''));
                        window.location.href = '/my/opms/submissions?submission_id=' + targetId + '&selected_only=1';
                    }

                    // Edit modal logic
                    let currentEditSubId = null;
                    let currentEditMeasurementType = 'text';
                    const editActualInput = document.getElementById('opms-edit-actual-value');
                    let fpEditInstance = null;

                    function configureEditActualInput(measurementType, value) {
                        currentEditMeasurementType = measurementType || 'text';
                        if (!editActualInput) {
                            return;
                        }
                        if (currentEditMeasurementType === 'date') {
                            editActualInput.type = 'text';
                            editActualInput.readOnly = true;
                            editActualInput.removeAttribute('placeholder');
                            if (!fpEditInstance) {
                                fpEditInstance = flatpickr(editActualInput, { dateFormat: 'd/m/Y', disableMobile: true });
                            }
                            if (value) { fpEditInstance.setDate(value, false, 'd/m/Y'); } else { fpEditInstance.clear(); }
                        } else {
                            if (fpEditInstance) { fpEditInstance.destroy(); fpEditInstance = null; }
                            editActualInput.type = 'text';
                            editActualInput.readOnly = false;
                            editActualInput.placeholder = 'Enter actual output value';
                            editActualInput.value = value || '';
                        }
                    }

                    function getCsrfToken() {
                        const hiddenInput = document.querySelector('input[name="csrf_token"]');
                        if (hiddenInput && hiddenInput.value) { return hiddenInput.value; }
                        const m = document.cookie.match(/(?:^|;\s*)csrf_token=([^;]+)/);
                        return m ? decodeURIComponent(m[1]) : '';
                    }
                    function showSubmissionNotice(message, level) {
                        const host = (document.getElementById('opms-portal-submission-form') || {}).parentElement
                            || document.querySelector('.opms-portal-shell');
                        if (!host) { return; }
                        let box = document.getElementById('opms-submission-inline-feedback');
                        if (!box) {
                            box = document.createElement('div');
                            box.id = 'opms-submission-inline-feedback';
                            host.prepend(box);
                        }
                        box.className = 'alert opms-inline-feedback alert-' + (level || 'warning') + ' mb-3';
                        box.textContent = message;
                    }
                    const pendingSubmissionDeleteIds = new Set();
                    async function openEditModal(subId) {
                        currentEditSubId = null;
                        const errorEl = document.getElementById('opms-edit-submission-error');
                        const metaEl = document.getElementById('opms-edit-submission-meta');
                        if (errorEl) { errorEl.classList.add('d-none'); errorEl.textContent = ''; }
                        try {
                            const resp = await fetch('/my/opms/submission/' + subId + '/load', { credentials: 'same-origin' });
                            const data = await resp.json();
                            if (!data.ok) { showSubmissionNotice(data.error || 'Cannot edit this submission.', 'danger'); return; }
                            currentEditSubId = subId;
                            if (metaEl) { metaEl.textContent = (data.indicator_name || '') + ' \u2014 ' + (data.quarter_label || ''); }
                            const fields2 = { 'opms-edit-comments': data.comments, 'opms-edit-reason': data.reason_for_deviation, 'opms-edit-remedial': data.remedial_actions };
                            Object.entries(fields2).forEach(([id, val]) => { const el = document.getElementById(id); if (el) { el.value = val || ''; } });
                            configureEditActualInput(data.measurement_type || 'text', data.actual_value_input || data.actual_value || '');
                            const modalEl = document.getElementById('opms-edit-submission-modal');
                            if (modalEl && window.bootstrap) { new window.bootstrap.Modal(modalEl).show(); }
                        } catch (err) { showSubmissionNotice('Failed to load submission data.', 'danger'); }
                    }

                    const saveBtn = document.getElementById('opms-edit-submission-save-btn');
                    if (saveBtn) {
                        saveBtn.addEventListener('click', async function () {
                            if (!currentEditSubId) { return; }
                            const errorEl = document.getElementById('opms-edit-submission-error');
                            const body = new URLSearchParams();
                            body.set('comments', (document.getElementById('opms-edit-comments') || {}).value || '');
                            body.set('actual_value', (document.getElementById('opms-edit-actual-value') || {}).value || '');
                            body.set('reason_for_deviation', (document.getElementById('opms-edit-reason') || {}).value || '');
                            body.set('remedial_actions', (document.getElementById('opms-edit-remedial') || {}).value || '');
                            try {
                                const resp = await fetch('/my/opms/submission/' + currentEditSubId + '/update', {
                                    method: 'POST', credentials: 'same-origin',
                                    headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'X-CSRFToken': getCsrfToken() },
                                    body: body.toString()
                                });
                                const data = await resp.json();
                                if (!data.ok) {
                                    if (errorEl) { errorEl.textContent = data.error || 'Update failed.'; errorEl.classList.remove('d-none'); }
                                    return;
                                }
                                // Close modal and reload
                                const modalEl = document.getElementById('opms-edit-submission-modal');
                                if (modalEl && window.bootstrap) { window.bootstrap.Modal.getInstance(modalEl).hide(); }
                                const quarterlyTarget = document.getElementById('quarterly_target_id');
                                if (quarterlyTarget && quarterlyTarget.value) {
                                    const payload = await fetchSelectionState(steps.length - 1);
                                    if (payload) { renderExistingSubmissions(payload.existing_submissions || []); }
                                }
                            } catch (err) {
                                if (errorEl) { errorEl.textContent = 'An error occurred while saving.'; errorEl.classList.remove('d-none'); }
                            }
                        });
                    }

                    async function deleteSubmission(subId, rowEl) {
                        const key = String(subId || '');
                        if (!pendingSubmissionDeleteIds.has(key)) {
                            pendingSubmissionDeleteIds.clear();
                            pendingSubmissionDeleteIds.add(key);
                            showSubmissionNotice('Click delete again to confirm. This action cannot be undone.', 'danger');
                            return;
                        }
                        pendingSubmissionDeleteIds.delete(key);
                        try {
                            const resp = await fetch('/my/opms/submission/' + subId + '/delete', {
                                method: 'POST', credentials: 'same-origin',
                                headers: { 'X-CSRFToken': getCsrfToken() }
                            });
                            const data = await resp.json();
                            if (!data.ok) { showSubmissionNotice(data.error || 'Could not delete submission.', 'danger'); return; }
                            const quarterlyTarget = document.getElementById('quarterly_target_id');
                            if (quarterlyTarget && quarterlyTarget.value) {
                                const payload = await fetchSelectionState(steps.length - 1);
                                if (payload) { renderExistingSubmissions(payload.existing_submissions || []); }
                            }
                        } catch (err) { showSubmissionNotice('Failed to delete submission.', 'danger'); }
                    }
                });

document.addEventListener('DOMContentLoaded', function () {
    let allSubmissionsData = [];
    let currentEditSubId = null;
    const seed = document.getElementById('opms-all-submissions-seed');
    let highlightedSubmissionId = (seed &amp;&amp; seed.dataset.selectedSubmissionId) || '';
    const statusColors = {
        'Approved': 'success', 'Submitted': 'primary', 'Director Review': 'info',
        'Draft': 'secondary', 'Rejected': 'danger'
    };

    function escHtml(str) {
        return String(str || '').replace(/&amp;/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    function getCsrfToken() {
        const hiddenInput = document.querySelector('input[name="csrf_token"]');
        if (hiddenInput &amp;&amp; hiddenInput.value) { return hiddenInput.value; }
        const match = document.cookie.match(/(?:^|;\s*)csrf_token=([^;]+)/);
        return match ? decodeURIComponent(match[1]) : '';
    }

    function showAllSubmissionsNotice(message, level) {
        const host = document.getElementById('opms-submissions-section');
        if (!host) { return; }
        let box = document.getElementById('opms-all-submissions-feedback');
        if (!box) {
            box = document.createElement('div');
            box.id = 'opms-all-submissions-feedback';
            const body = host.querySelector('.card-body.pb-0');
            if (body) {
                body.prepend(box);
            } else {
                host.prepend(box);
            }
        }
        box.className = 'alert opms-inline-feedback alert-' + (level || 'warning') + ' mb-3';
        box.textContent = message;
    }

    const pendingAllSubmissionDeleteIds = new Set();

    function highlightSubmission(subId) {
        if (!subId) { return; }
        document.querySelectorAll('.opms-all-sub-highlight').forEach(function (el) {
            el.classList.remove('opms-all-sub-highlight');
        });
        const target = document.getElementById('opms-all-sub-row-' + subId);
        if (!target) { return; }
        target.classList.add('opms-all-sub-highlight');
        target.scrollIntoView({ behavior: 'smooth', block: 'center' });
        window.setTimeout(function () {
            target.classList.remove('opms-all-sub-highlight');
        }, 3000);
    }

    function renderAllSubmissions() {
        const tbody = document.getElementById('opms-all-submissions-body');
        const badge = document.getElementById('opms-all-submissions-badge');
        if (!tbody) { return; }
        const qVal = (document.getElementById('opms-filter-quarter') || {}).value || '';
        const stVal = (document.getElementById('opms-filter-status') || {}).value || '';
        const srVal = ((document.getElementById('opms-filter-search') || {}).value || '').toLowerCase().trim();
        const filtered = allSubmissionsData.filter(function (sub) {
            if (qVal &amp;&amp; sub.quarter_code !== qVal) { return false; }
            if (stVal &amp;&amp; sub.workflow_status !== stVal) { return false; }
            if (srVal &amp;&amp; !((sub.indicator_name || '').toLowerCase().includes(srVal) || (sub.name || '').toLowerCase().includes(srVal) || (sub.submitted_by || '').toLowerCase().includes(srVal))) {
                return false;
            }
            return true;
        });

        if (badge) {
            badge.textContent = filtered.length + ' / ' + allSubmissionsData.length + ' submission' + (allSubmissionsData.length !== 1 ? 's' : '');
            badge.className = 'badge bg-secondary';
        }

        tbody.innerHTML = '';
        if (!filtered.length) {
            tbody.innerHTML = '&lt;tr&gt;&lt;td colspan="9" class="text-center text-muted py-3"&gt;No submissions found.&lt;/td&gt;&lt;/tr&gt;';
            return;
        }

        filtered.forEach(function (sub, idx) {
            const tr = document.createElement('tr');
            tr.id = 'opms-all-sub-row-' + sub.id;
            tr.setAttribute('data-sub-id', String(sub.id));
            const isOpen = sub.is_quarter_open === true;
            const statusColor = statusColors[sub.workflow_status] || 'secondary';
            const shortComment = (sub.comments || '-').length > 60 ? (sub.comments || '-').substring(0, 60) + '...' : (sub.comments || '-');
            const cells = [
                '<td class="text-muted">' + String(idx + 1) + '</td>',
                '<td><small>' + escHtml(sub.indicator_name || '-') + '</small></td>',
                '<td><span class="badge bg-light text-dark border">' + escHtml(sub.quarter_code || '-') + '</span></td>',
                '<td>' + escHtml(sub.submitted_by || '-') + '</td>',
                '<td><small>' + escHtml(sub.submission_date || '-') + '</small></td>',
                '<td>' + escHtml(sub.actual_value || '-') + '</td>',
                '<td><span class="badge text-bg-' + statusColor + '">' + escHtml(sub.workflow_status || '-') + '</span></td>',
                '<td><small class="text-muted">' + escHtml(shortComment) + '</small></td>',
            ];
            tr.innerHTML = cells.join('');

            const actionsCell = document.createElement('td');
            actionsCell.className = 'text-nowrap';

            const editBtn = document.createElement('button');
            editBtn.type = 'button';
            editBtn.className = 'btn btn-sm me-1 ' + (isOpen ? 'btn-outline-primary opms-sub-action-edit' : 'btn-outline-secondary opms-sub-action-locked');
            const hasEvidence = Number(sub.evidence_count || 0) > 0;
            const editLabel = hasEvidence ? 'Update Submission' : 'Add Evidence';
            editBtn.innerHTML = isOpen ? '<i class="fa fa-pencil"></i> ' + editLabel : '<i class="fa fa-lock"></i> Locked';
            editBtn.title = isOpen ? editLabel : 'Quarter is closed - locked';
            editBtn.disabled = !isOpen;
            if (isOpen) {
                editBtn.addEventListener('click', function () { openEditModal(sub.id); });
            }

            const deleteBtn = document.createElement('button');
            deleteBtn.type = 'button';
            deleteBtn.className = 'btn btn-sm ' + (isOpen ? 'btn-outline-danger opms-sub-action-delete' : 'btn-outline-secondary opms-sub-action-locked');
            deleteBtn.innerHTML = isOpen ? '<i class="fa fa-trash"></i>' : '<i class="fa fa-lock"></i>';
            deleteBtn.title = isOpen ? 'Delete submission' : 'Quarter is closed - locked';
            deleteBtn.disabled = !isOpen;
            if (isOpen) {
                deleteBtn.addEventListener('click', function () { deleteSubmission(sub.id); });
            }

            actionsCell.appendChild(editBtn);
            actionsCell.appendChild(deleteBtn);
            tr.appendChild(actionsCell);
            tbody.appendChild(tr);
        });

        if (highlightedSubmissionId) {
            window.setTimeout(function () {
                highlightSubmission(highlightedSubmissionId);
            }, 150);
        }
    }

    async function loadAllSubmissions() {
        const tbody = document.getElementById('opms-all-submissions-body');
        const badge = document.getElementById('opms-all-submissions-badge');
        try {
            const response = await fetch('/my/opms/submissions/all', { credentials: 'same-origin' });
            const payload = await response.json();
            allSubmissionsData = (payload &amp;&amp; Array.isArray(payload.submissions)) ? payload.submissions : [];
            const quarterFilter = document.getElementById('opms-filter-quarter');
            if (quarterFilter) {
                const quarters = Array.from(new Set(allSubmissionsData.map(function (sub) { return sub.quarter_code; }).filter(Boolean))).sort();
                quarterFilter.replaceChildren();
                const defaultOption = document.createElement('option');
                defaultOption.value = '';
                defaultOption.textContent = 'All Quarters';
                quarterFilter.appendChild(defaultOption);
                quarters.forEach(function (quarterCode) {
                    const option = document.createElement('option');
                    option.value = quarterCode;
                    option.textContent = quarterCode;
                    quarterFilter.appendChild(option);
                });
            }
            renderAllSubmissions();
        } catch (error) {
            if (tbody) {
                tbody.innerHTML = '&lt;tr&gt;&lt;td colspan="9" class="text-center text-danger py-3"&gt;Failed to load submissions.&lt;/td&gt;&lt;/tr&gt;';
            }
            if (badge) {
                badge.textContent = 'Error';
                badge.className = 'badge bg-danger';
            }
        }
    }

    async function openEditModal(subId) {
        currentEditSubId = null;
        const errorEl = document.getElementById('opms-edit-submission-error');
        const metaEl = document.getElementById('opms-edit-submission-meta');
        if (errorEl) {
            errorEl.classList.add('d-none');
            errorEl.textContent = '';
        }
        try {
            const response = await fetch('/my/opms/submission/' + subId + '/load', { credentials: 'same-origin' });
            const payload = await response.json();
            if (!payload.ok) {
                showAllSubmissionsNotice(payload.error || 'Cannot edit this submission.', 'danger');
                return;
            }
            currentEditSubId = subId;
            if (metaEl) {
                metaEl.textContent = (payload.indicator_name || '') + ' - ' + (payload.quarter_label || '');
            }
            const fieldMap = {
                'opms-edit-actual-value': payload.actual_value,
                'opms-edit-comments': payload.comments,
                'opms-edit-reason': payload.reason_for_deviation,
                'opms-edit-remedial': payload.remedial_actions,
            };
            Object.entries(fieldMap).forEach(function (entry) {
                const el = document.getElementById(entry[0]);
                if (el) { el.value = entry[1] || ''; }
            });
            const modalEl = document.getElementById('opms-edit-submission-modal');
            if (modalEl &amp;&amp; window.bootstrap) {
                new window.bootstrap.Modal(modalEl).show();
            }
        } catch (error) {
            showAllSubmissionsNotice('Failed to load submission data.', 'danger');
        }
    }

    const saveBtn = document.getElementById('opms-edit-submission-save-btn');
    if (saveBtn) {
        saveBtn.addEventListener('click', async function () {
            if (!currentEditSubId) { return; }
            const errorEl = document.getElementById('opms-edit-submission-error');
            const body = new URLSearchParams();
            body.set('comments', (document.getElementById('opms-edit-comments') || {}).value || '');
            body.set('actual_value', (document.getElementById('opms-edit-actual-value') || {}).value || '');
            body.set('reason_for_deviation', (document.getElementById('opms-edit-reason') || {}).value || '');
            body.set('remedial_actions', (document.getElementById('opms-edit-remedial') || {}).value || '');
            try {
                const response = await fetch('/my/opms/submission/' + currentEditSubId + '/update', {
                    method: 'POST',
                    credentials: 'same-origin',
                    headers: {
                        'Content-Type': 'application/x-www-form-urlencoded',
                        'X-CSRFToken': getCsrfToken(),
                    },
                    body: body.toString(),
                });
                const payload = await response.json();
                if (!payload.ok) {
                    if (errorEl) {
                        errorEl.textContent = payload.error || 'Update failed.';
                        errorEl.classList.remove('d-none');
                    }
                    return;
                }
                const modalEl = document.getElementById('opms-edit-submission-modal');
                if (modalEl &amp;&amp; window.bootstrap) {
                    window.bootstrap.Modal.getInstance(modalEl).hide();
                }
                highlightedSubmissionId = String(currentEditSubId);
                await loadAllSubmissions();
            } catch (error) {
                if (errorEl) {
                    errorEl.textContent = 'An error occurred while saving.';
                    errorEl.classList.remove('d-none');
                }
            }
        });
    }

    async function deleteSubmission(subId) {
        const key = String(subId || '');
        if (!pendingAllSubmissionDeleteIds.has(key)) {
            pendingAllSubmissionDeleteIds.clear();
            pendingAllSubmissionDeleteIds.add(key);
            showAllSubmissionsNotice('Click delete again to confirm. This action cannot be undone.', 'danger');
            return;
        }
        pendingAllSubmissionDeleteIds.delete(key);
        try {
            const response = await fetch('/my/opms/submission/' + subId + '/delete', {
                method: 'POST',
                credentials: 'same-origin',
                headers: { 'X-CSRFToken': getCsrfToken() },
            });
            const payload = await response.json();
            if (!payload.ok) {
                showAllSubmissionsNotice(payload.error || 'Could not delete submission.', 'danger');
                return;
            }
            highlightedSubmissionId = '';
            await loadAllSubmissions();
        } catch (error) {
            showAllSubmissionsNotice('Failed to delete submission.', 'danger');
        }
    }

    ['opms-filter-quarter', 'opms-filter-status', 'opms-filter-search'].forEach(function (id) {
        const el = document.getElementById(id);
        if (el) {
            el.addEventListener('input', renderAllSubmissions);
            el.addEventListener('change', renderAllSubmissions);
        }
    });

    const clearBtn = document.getElementById('opms-filter-clear-btn');
    if (clearBtn) {
        clearBtn.addEventListener('click', function () {
            ['opms-filter-quarter', 'opms-filter-status', 'opms-filter-search'].forEach(function (id) {
                const el = document.getElementById(id);
                if (el) { el.value = ''; }
            });
            renderAllSubmissions();
        });
    }

    loadAllSubmissions();
});

document.addEventListener('DOMContentLoaded', function () {
    const selectedSeed = document.getElementById('opms-selected-filters-seed');
    const settingsSeed = document.getElementById('opms-settings-seed');
    const enableNarratives = !(settingsSeed && settingsSeed.dataset.enableNarratives === '0');

    function safeJsonParse(rawValue, fallback) {
        try {
            return JSON.parse(rawValue);
        } catch (error) {
            return fallback;
        }
    }

    const initialFilters = safeJsonParse((selectedSeed && selectedSeed.dataset.filters) || '{}', {});
    const statusSelect = document.getElementById('view-status');
    const validStatuses = ['unknown', 'behind', 'met', 'exceeded'];

    const steps = [
        { id: 'financial_year_id', key: 'financial_years', placeholder: 'Select Financial Year' },
        { id: 'programme_id', key: 'programmes', placeholder: 'Select Programme' },
        { id: 'sub_programme_id', key: 'sub_programmes', placeholder: 'Select Sub-Programme' },
        { id: 'directorate_id', key: 'directorates', placeholder: 'Select Directorate' },
        { id: 'output_id', key: 'outputs', placeholder: 'Select Output' },
        { id: 'output_indicator_id', key: 'output_indicators', placeholder: 'Select Output Indicator' },
        { id: 'quarter_id', key: 'quarters', placeholder: 'Select Quarter' },
    ];
    const desiredInitial = {};
    const optionCache = {};
    let refreshToken = 0;

    const normalizedId = (value) => {
        const strValue = String(value || '').trim();
        return /^\d+$/.test(strValue) ? strValue : '';
    };

    steps.forEach((step) => {
        desiredInitial[step.id] = normalizedId(initialFilters[step.id]);
    });
    if (statusSelect) {
        const initialStatus = String(initialFilters.status || '').trim().toLowerCase();
        statusSelect.value = validStatuses.includes(initialStatus) ? initialStatus : '';
    }

    function getSelect(id) {
        return document.getElementById('view-' + id);
    }

    function refillSelect(selectId, values, placeholder) {
        const select = getSelect(selectId);
        if (!select) {
            return;
        }
        select.replaceChildren();
        const defaultOption = document.createElement('option');
        defaultOption.value = '';
        defaultOption.textContent = placeholder;
        select.appendChild(defaultOption);
        (values || []).forEach((entry) => {
            const option = document.createElement('option');
            option.value = entry.id;
            option.textContent = entry.name;
            select.appendChild(option);
        });
    }

    function normalizeOptionEntries(values) {
        return (values || []).map((entry) => ({
            id: String(entry.id),
            name: entry.name,
        }));
    }

    function mergeOptionEntries(baseEntries, incomingEntries) {
        const merged = [];
        const seen = new Set();

        (baseEntries || []).forEach((entry) => {
            const key = String(entry.id);
            if (!seen.has(key)) {
                seen.add(key);
                merged.push({ id: key, name: entry.name });
            }
        });

        (incomingEntries || []).forEach((entry) => {
            const key = String(entry.id);
            if (!seen.has(key)) {
                seen.add(key);
                merged.push({ id: key, name: entry.name });
            }
        });

        return merged;
    }

    function getEffectiveOptions(stepId, payloadOptions, currentValue) {
        const normalized = normalizeOptionEntries(payloadOptions);
        const cached = optionCache[stepId] || [];
        const merged = mergeOptionEntries(cached, normalized);

        if (merged.length > 1) {
            optionCache[stepId] = merged;
        }

        const currentIsSet = !!String(currentValue || '').trim();
        const payloadTooNarrow = normalized.length <= 1;
        const hasBroadCache = (optionCache[stepId] || []).length > 1;

        if (currentIsSet && payloadTooNarrow && hasBroadCache) {
            return optionCache[stepId];
        }

        return normalized;
    }

    function selectedParams() {
        const params = new URLSearchParams();

        for (let i = 0; i < steps.length; i += 1) {
            const id = steps[i].id;
            const select = getSelect(id);
            const value = select ? normalizedId(select.value) : '';
            if (value) {
                params.set(id, value);
            }
        }
        const statusValue = String((statusSelect && statusSelect.value) || '').trim().toLowerCase();
        if (validStatuses.includes(statusValue)) {
            params.set('status', statusValue);
        }
        return params;
    }

    async function fetchSelectionState() {
        const response = await fetch('/my/opms/hierarchy/options?' + selectedParams().toString(), {
            credentials: 'same-origin',
        });
        if (!response.ok) {
            return null;
        }
        return response.json();
    }

    function statusBadge(status) {
        if (status === 'met') return 'bg-success';
        if (status === 'exceeded') return 'bg-success';
        if (status === 'behind') return 'bg-warning text-dark';
        if (status === 'unknown') return 'opms-badge-not-submitted';
        if (status === 'n/a') return 'bg-secondary';
        return 'bg-secondary';
    }

    function triggerIndicatorResultsPrint() {
        document.body.classList.add('opms-print-indicator-results');
        window.print();
    }

    window.addEventListener('afterprint', function () {
        document.body.classList.remove('opms-print-indicator-results');
    });

    function renderRows(payload) {
        const tbody = document.getElementById('opms-view-results-body');
        const thead = document.getElementById('opms-view-results-head');
        const table = document.getElementById('opms-view-results-table');
        const badge = document.getElementById('opms-view-count-badge');
        const quarterSelect = getSelect('quarter_id');
        if (!tbody || !thead || !table || !badge) {
            return;
        }

        const rows = (payload && payload.rows) || [];
        const payloadQuarterCodes = (payload && payload.quarter_codes) || [];
        const selectedQuarterId = normalizedId(quarterSelect ? quarterSelect.value : '');

        const quarterSortRank = (code) => {
            const match = String(code || '').toUpperCase().match(/\d+/);
            return match ? parseInt(match[0], 10) : 999;
        };

        const uniqueQuarterCodes = [...new Set(payloadQuarterCodes.map((code) => String(code || '').toUpperCase()).filter(Boolean))]
            .sort((a, b) => quarterSortRank(a) - quarterSortRank(b) || a.localeCompare(b));

        let quarterCodes = uniqueQuarterCodes.length ? uniqueQuarterCodes : ['Q1', 'Q2', 'Q3', 'Q4'];
        if (selectedQuarterId && quarterSelect) {
            const selectedOption = quarterSelect.options[quarterSelect.selectedIndex];
            const selectedLabel = String((selectedOption && selectedOption.textContent) || '').trim();
            const selectedCode = selectedLabel ? selectedLabel.split('-')[0].trim().toUpperCase() : '';
            if (selectedCode) {
                quarterCodes = [selectedCode];
            } else if (uniqueQuarterCodes.length) {
                quarterCodes = [uniqueQuarterCodes[0]];
            }
        }

        table.classList.toggle('opms-view-single-quarter', quarterCodes.length === 1);
        table.classList.toggle('opms-view-multi-quarter', quarterCodes.length > 1);

        const createHeader = (activeQuarterCodes) => {
            thead.replaceChildren();
            const headerRow = document.createElement('tr');

            const indicatorHead = document.createElement('th');
            indicatorHead.className = 'opms-col-output-indicator';
            indicatorHead.textContent = 'Output Indicator';
            headerRow.appendChild(indicatorHead);

            const annualHead = document.createElement('th');
            annualHead.className = 'opms-col-slim opms-col-annual opms-col-annual-fixed';
            annualHead.textContent = 'Annual Target';
            headerRow.appendChild(annualHead);

            const annualActualHead = document.createElement('th');
            annualActualHead.className = 'opms-col-slim opms-col-annual opms-col-actual-highlight';
            const annualActualLink = document.createElement('a');
            annualActualLink.textContent = 'Annual Actual';
            annualActualLink.href = '#';
            annualActualLink.style.color = 'inherit';
            annualActualLink.style.textDecoration = 'underline';
            annualActualLink.style.cursor = 'pointer';
            annualActualLink.title = 'Print this view to PDF';
            annualActualLink.addEventListener('click', (e) => {
                e.preventDefault();
                triggerIndicatorResultsPrint();
            });
            annualActualHead.appendChild(annualActualLink);

            const annualVarianceHead = document.createElement('th');
            annualVarianceHead.className = 'opms-col-slim opms-col-annual';
            annualVarianceHead.textContent = 'Annual Deviation';

            const quarterMetrics = enableNarratives
                ? ['Planned', 'Actual', 'Deviation', 'Narratives', 'Evidence', 'Submissions', 'Status']
                : ['Planned', 'Actual', 'Deviation', 'Evidence', 'Submissions', 'Status'];

            activeQuarterCodes.forEach((qc) => {
                quarterMetrics.forEach((suffix) => {
                    const th = document.createElement('th');
                    const colName = `${qc} ${suffix}`;

                    if (suffix === 'Planned') {
                        th.className = 'opms-col-slim opms-col-planned-highlight';
                    } else if (suffix === 'Actual') {
                        th.className = 'opms-col-slim opms-col-actual-highlight';
                    } else {
                        th.className = 'opms-col-slim';
                    }

                    if (suffix === 'Actual') {
                        const link = document.createElement('a');
                        link.textContent = colName;
                        link.href = '#';
                        link.style.color = 'inherit';
                        link.style.textDecoration = 'underline';
                        link.style.cursor = 'pointer';
                        link.addEventListener('click', (e) => {
                            e.preventDefault();
                            const params = selectedParams();
                            const selectedQuarterId = normalizedId(quarterSelect ? quarterSelect.value : '');
                            if (selectedQuarterId) {
                                params.set('quarter_id', selectedQuarterId);
                            } else {
                                params.delete('quarter_id');
                            }
                            params.set('clicked_quarter_code', String(qc || '').toUpperCase());
                            const downloadUrl = '/my/opms/view/download-report?' + params.toString();
                            window.location.href = downloadUrl;
                        });
                        th.appendChild(link);
                    } else {
                        th.textContent = colName;
                    }
                    headerRow.appendChild(th);
                });
            });

            headerRow.appendChild(annualActualHead);
            headerRow.appendChild(annualVarianceHead);
            thead.appendChild(headerRow);
        };

        const clearBody = () => {
            tbody.replaceChildren();
        };

        const createCell = (label, value, className) => {
            const cell = document.createElement('td');
            cell.setAttribute('data-label', label);
            if (className) {
                cell.className = className;
            }
            cell.textContent = value;
            return cell;
        };

        const createLinkCell = (label, text, href, className) => {
            const cell = document.createElement('td');
            cell.setAttribute('data-label', label);
            if (className) {
                cell.className = className;
            }
            const link = document.createElement('a');
            link.href = href;
            link.textContent = text;
            link.className = 'opms-view-evidence-link fw-semibold text-decoration-underline';
            cell.appendChild(link);
            return cell;
        };

        const deviationToneClass = (rawValue) => {
            const value = String(rawValue || '').trim();
            if (!value || value === '-' || value.toLowerCase() === 'n/a') {
                return '';
            }
            const normalized = value.replace(/,/g, '');
            const match = normalized.match(/[-+]?\d*\.?\d+/);
            if (!match) {
                return '';
            }
            const numeric = parseFloat(match[0]);
            if (Number.isNaN(numeric)) {
                return '';
            }
            if (numeric > 0) {
                return 'opms-deviation-positive';
            }
            if (numeric < 0) {
                return 'opms-deviation-negative';
            }
            return 'opms-deviation-zero';
        };

        const appendEmptyRow = (message) => {
            clearBody();
            const row = document.createElement('tr');
            const cell = document.createElement('td');
            cell.colSpan = Math.max(4 + (quarterCodes.length * (enableNarratives ? 7 : 6)), 4);
            cell.className = 'text-center text-muted py-4';
            cell.textContent = message;
            row.appendChild(cell);
            tbody.appendChild(row);
        };

        createHeader(quarterCodes);

        if (!rows.length) {
            badge.textContent = '0 indicators';
            appendEmptyRow('No indicators found for the current filters.');
            return;
        }

        const grouped = {};
        rows.forEach((row) => {
            const key = String(row.output_indicator || '-') + '||' + String(row.output || '-') + '||' + String(row.annual_target || '-');
            if (!grouped[key]) {
                grouped[key] = {
                    output_indicator: row.output_indicator || '-',
                    annual_actual: row.annual_actual || '-',
                    annual_target: row.annual_target || '-',
                    annual_variance: row.annual_variance || '-',
                    quarters: {},
                };
            }
            const qc = String(row.quarter_code || '').toUpperCase();
            if (qc) {
                grouped[key].quarters[qc] = row;
            }
        });

        const groupedRows = Object.values(grouped);
        badge.textContent = groupedRows.length + ' indicators';

        clearBody();
        const fragment = document.createDocumentFragment();
        groupedRows.forEach((row) => {
            const tr = document.createElement('tr');
            tr.appendChild(createCell('Output Indicator', String(row.output_indicator || '-'), 'opms-col-output-indicator'));
            tr.appendChild(createCell('Annual Target', String(row.annual_target || '-'), 'opms-col-slim opms-col-annual opms-col-annual-fixed'));

            quarterCodes.forEach((qc) => {
                const qRow = row.quarters[qc] || null;
                tr.appendChild(createCell(qc + ' Planned', String(qRow ? qRow.planned : '-'), 'opms-col-slim'));
                tr.appendChild(createCell(qc + ' Actual', String(qRow ? qRow.actual : '-'), 'opms-col-slim'));
                const deviationValue = String(qRow ? qRow.variance : '-');
                const deviationClass = deviationToneClass(deviationValue);
                tr.appendChild(createCell(qc + ' Deviation', deviationValue, 'opms-col-slim' + (deviationClass ? ' ' + deviationClass : '')));
                if (enableNarratives) {
                    const narrativeText = String(qRow ? qRow.narrative_texts || '-' : '-');
                    const narrativeShort = narrativeText.length > 120 ? narrativeText.substring(0, 120) + '\u2026' : narrativeText;
                    tr.appendChild(createCell(qc + ' Narratives', narrativeShort, 'opms-col-slim'));
                }
                if (qRow && Number(qRow.evidence_count || 0) > 0 && qRow.evidence_target_url) {
                    tr.appendChild(createLinkCell(qc + ' Evidence', 'View', String(qRow.evidence_target_url), 'opms-col-slim'));
                } else {
                    tr.appendChild(createCell(qc + ' Evidence', '-', 'opms-col-slim'));
                }
                tr.appendChild(createCell(qc + ' Submissions', String(qRow ? qRow.submission_count || 0 : '-'), 'opms-col-slim'));

                const statusCell = document.createElement('td');
                statusCell.className = 'opms-col-slim';
                statusCell.setAttribute('data-label', qc + ' Status');
                const badgeEl = document.createElement('span');
                const qStatus = (qRow ? String(qRow.status || 'unknown') : 'n/a').trim().toLowerCase();
                const statusLabels = { 'met': 'Achieved', 'exceeded': 'Exceeded', 'behind': 'Not-Achieved', 'unknown': 'Not Submitted', 'n/a': 'N/A' };
                const badgeClass = (qStatus === 'n/a') ? 'opms-badge-na' : statusBadge(qStatus);
                badgeEl.className = 'badge ' + badgeClass;
                badgeEl.classList.add('opms-status-badge-wrap');
                if (qStatus === 'unknown') {
                    badgeEl.classList.add('opms-status-badge-stack');
                    badgeEl.innerHTML = 'Not<br>Submitted';
                } else {
                    badgeEl.textContent = statusLabels[qStatus] || qStatus;
                }
                statusCell.appendChild(badgeEl);
                tr.appendChild(statusCell);
            });

            tr.appendChild(createCell('Annual Actual', String(row.annual_actual || '-'), 'opms-col-slim opms-col-annual'));
            const annualDevClass = deviationToneClass(String(row.annual_variance || '-'));
            tr.appendChild(createCell('Annual Deviation', String(row.annual_variance || '-'), 'opms-col-slim opms-col-annual' + (annualDevClass ? ' ' + annualDevClass : '')));

            fragment.appendChild(tr);
        });
        tbody.appendChild(fragment);
    }

    const annualActualPrintLink = document.getElementById('opms-annual-actual-print-link');
    if (annualActualPrintLink) {
        annualActualPrintLink.addEventListener('click', function (e) {
            e.preventDefault();
            triggerIndicatorResultsPrint();
        });
    }

    async function refreshRows() {
        const params = selectedParams();
        const response = await fetch('/my/opms/view/data?' + params.toString(), {
            credentials: 'same-origin',
        });
        if (!response.ok) {
            renderRows({ rows: [], count: 0 });
            return;
        }
        const payload = await response.json();
        renderRows(payload);
    }

    function syncFilterOptions(payload, applyDesired) {
        let changed = false;

        steps.forEach((step) => {
            const select = getSelect(step.id);
            if (!select) {
                return;
            }

            const options = payload[step.key] || [];
            const currentValue = normalizedId(select.value);
            const effectiveOptions = getEffectiveOptions(step.id, options, currentValue);
            const currentExists = effectiveOptions.some((entry) => String(entry.id) === currentValue);
            const desiredValue = normalizedId(desiredInitial[step.id]);
            const desiredExists = effectiveOptions.some((entry) => String(entry.id) === desiredValue);

            refillSelect(step.id, effectiveOptions, step.placeholder);

            let nextValue = '';
            if (currentValue && currentExists) {
                nextValue = currentValue;
            } else if (applyDesired && desiredValue && desiredExists) {
                nextValue = desiredValue;
                desiredInitial[step.id] = '';
            }

            if (String(select.value || '') !== String(nextValue || '')) {
                changed = true;
            }
            select.value = String(nextValue || '');
        });

        return changed;
    }

    async function refreshAll(applyDesired) {
        const token = ++refreshToken;
        let loopApplyDesired = !!applyDesired;

        for (let i = 0; i < 4; i += 1) {
            const payload = await fetchSelectionState();
            if (token !== refreshToken || !payload) {
                return;
            }
            const changed = syncFilterOptions(payload, loopApplyDesired);
            if (!loopApplyDesired || !changed) {
                break;
            }
            loopApplyDesired = false;
        }

        if (token !== refreshToken) {
            return;
        }
        await refreshRows();
    }

    async function backfillAncestors(changedStepIndex, payload) {
        const changedStep = steps[changedStepIndex];
        const changedSelect = getSelect(changedStep.id);
        if (!changedSelect || !changedSelect.value) {
            return;
        }

        const hierarchyPath = extractHierarchyPath(changedStepIndex, changedSelect.value, payload);

        for (let i = 0; i < changedStepIndex; i += 1) {
            const ancestorStep = steps[i];
            const ancestorSelect = getSelect(ancestorStep.id);
            if (ancestorSelect && hierarchyPath[ancestorStep.id]) {
                const ancestorValue = String(hierarchyPath[ancestorStep.id]);
                if (ancestorValue && ancestorValue !== ancestorSelect.value) {
                    ancestorSelect.value = ancestorValue;
                    if (ancestorSelect._opmsComboboxSyncDisplay) {
                        ancestorSelect._opmsComboboxSyncDisplay();
                    }
                }
            }
        }
    }

    function extractHierarchyPath(stepIndex, selectedValue, payload) {
        const path = {};
        const changedStep = steps[stepIndex];

        const entries = payload[changedStep.key] || [];
        const selected = entries.find((e) => String(e.id) === String(selectedValue));

        if (!selected) {
            return path;
        }

        if (selected.financial_year_id) path.financial_year_id = selected.financial_year_id;
        if (selected.programme_id) path.programme_id = selected.programme_id;
        if (selected.sub_programme_id) path.sub_programme_id = selected.sub_programme_id;
        if (selected.directorate_id) path.directorate_id = selected.directorate_id;
        if (selected.output_id) path.output_id = selected.output_id;
        if (selected.output_indicator_id) path.output_indicator_id = selected.output_indicator_id;

        return path;
    }

    steps.forEach((step) => {
        const select = getSelect(step.id);
        if (select) {
            select.addEventListener('change', async () => {
                const stepIndex = steps.findIndex((s) => s.id === step.id);

                if (stepIndex > 0) {
                    const currentPayload = await fetchSelectionState();
                    if (currentPayload) {
                        await backfillAncestors(stepIndex, currentPayload);
                    }
                }

                await refreshAll(false);
            });
        }
    });
    if (statusSelect) {
        statusSelect.addEventListener('change', async () => {
            await refreshRows();
        });
    }

    const clearBtn = document.getElementById('opms-view-clear-filters');
    if (clearBtn) {
        clearBtn.addEventListener('click', async () => {
            steps.forEach((step) => {
                desiredInitial[step.id] = '';
                const select = getSelect(step.id);
                if (select) {
                    select.value = '';
                    if (typeof select._opmsComboboxSyncDisplay === 'function') {
                        select._opmsComboboxSyncDisplay();
                    }
                }
            });
            if (statusSelect) {
                statusSelect.value = '';
            }
            await refreshAll(false);
        });
    }

    refreshAll(true);
});

                document.addEventListener('DOMContentLoaded', function () {
