                    function renderWorkflowPie() {
                        const pieContainer = document.getElementById('opms-workflow-pie');
                        const legendContainer = document.getElementById('opms-workflow-pie-legend');
                        const rows = (dashboard.workflow_pie_rows || []).map((row) => Object.assign({ enabled: true }, row));
                        if (!pieContainer || !legendContainer || !rows.length) {
                            return;
                        }

                        function paint() {
                            const activeRows = rows.filter((row) => row.enabled && row.count > 0);
                            const total = activeRows.reduce((sum, row) => sum + Number(row.count || 0), 0);
                            if (!total) {
                                pieContainer.style.background = 'conic-gradient(#e2e8f0 0 100%)';
                                pieContainer.innerHTML = '
0No data';
                                return;
                            }

                            let cursor = 0;
                            const parts = activeRows.map((row) => {
                                const pct = (Number(row.count || 0) / total) * 100;
                                const start = cursor;
                                const end = Math.min(100, cursor + pct);
                                cursor = end;
                                return row.color + ' ' + start.toFixed(2) + '% ' + end.toFixed(2) + '%';
                            });

                            pieContainer.style.background = 'conic-gradient(' + parts.join(', ') + ')';
                            pieContainer.innerHTML = '
' + total + 'Active slices';
                        }

                        legendContainer.innerHTML = '';
                        rows.forEach((row) => {
                            const btn = document.createElement('button');
                            btn.type = 'button';
                            btn.className = 'opms-chart-toggle is-on';
                            btn.innerHTML = '' +
                                '' + row.label + '' +
                                '' + row.count + '';
                            btn.addEventListener('click', function () {
                                row.enabled = !row.enabled;
                                btn.classList.toggle('is-on', row.enabled);
                                paint();
                            });
                            legendContainer.appendChild(btn);
                        });

                        paint();
                    }

                    function renderQuarterBars(metric) {
                        const container = document.getElementById('opms-quarter-activity-chart');
