                        }, 0) || 1;

                        const isPercent = metric === 'load_percent';
                        const metricLabel = isPercent ? 'Load %' : (metric === 'evidence' ? 'Evidence' : 'Submissions');
                        const totalValue = rows.reduce((sum, row) => sum + Number(row[metric] || 0), 0);
                        const avgValue = rows.length ? (totalValue / rows.length) : 0;
                        const highestRow = rows.reduce(
