                                const coveragePct = targets ? (loaded / targets) * 100 : 0;
                                const fill = targets ? Math.max(6, Math.round(coveragePct)) : 0;
                                const state = getCoverageState(coveragePct);
                                return (
                                    '
' +
                                        '
' +
