document.addEventListener('DOMContentLoaded', function () {
    function getCsrfToken() {
        const hidden = document.querySelector('input[name="csrf_token"]');
        return hidden ? hidden.value : '';
    }

    function showEvidenceNotice(message, level) {
        const host = document.querySelector('.opms-portal-shell');
        if (!host) { return; }
        let box = document.getElementById('opms-evidence-feedback');
        if (!box) {
            box = document.createElement('div');
            box.id = 'opms-evidence-feedback';
            host.prepend(box);
        }
        box.className = 'alert opms-inline-feedback alert-' + (level || 'warning') + ' mb-3';
        box.textContent = message;
    }

    const pendingEvidenceDeleteIds = new Set();

    async function deleteEvidence(evidenceId, rowEl) {
        const key = String(evidenceId || '');
        if (!pendingEvidenceDeleteIds.has(key)) {
            pendingEvidenceDeleteIds.clear();
            pendingEvidenceDeleteIds.add(key);
            showEvidenceNotice('Click delete again to confirm. This action cannot be undone.', 'danger');
            return;
        }
        pendingEvidenceDeleteIds.delete(key);
        try {
            const body = new URLSearchParams();
            body.set('csrf_token', getCsrfToken());
            const resp = await fetch('/my/opms/evidence/' + evidenceId + '/delete', {
                method: 'POST',
                credentials: 'same-origin',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                    'X-CSRFToken': getCsrfToken()
                },
                body: body.toString()
            });
            const contentType = resp.headers.get('content-type') || '';
            if (contentType.indexOf('application/json') === -1) {
                showEvidenceNotice('Delete failed: unexpected server response. Please refresh and try again.', 'danger');
                return;
            }
            const data = await resp.json();
            if (!data.ok) {
                showEvidenceNotice(data.error || 'Could not delete evidence file.', 'danger');
                return;
            }
            if (rowEl) {
                rowEl.remove();
            }
            window.location.reload();
        } catch (err) {
            showEvidenceNotice('Failed to delete evidence file.', 'danger');
        }
    }

    document.querySelectorAll('.opms-evidence-delete').forEach((button) => {
        button.addEventListener('click', function () {
            const evidenceId = button.getAttribute('data-evidence-id');
            const rowEl = button.closest('tr');
            if (!evidenceId) {
                return;
            }
            deleteEvidence(evidenceId, rowEl);
        });
    });
});
